<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/app.php';
require_once __DIR__ . '/../includes/business_profile.php';
require_once __DIR__ . '/../includes/customer_referrals.php';
require_once __DIR__ . '/../includes/referral_opportunities.php';
require_once __DIR__ . '/../includes/reports.php';
$user = require_login('BUSINESS', true);
if (!business_profile_is_complete((int) $user['id'])) { set_flash('warning', 'Complete your business profile before opening reports.'); redirect('business/profile.php'); }
$businessId = (int) $user['id']; $type = in_array($_GET['type'] ?? '', BUSINESS_REPORT_TYPES, true) ? (string) $_GET['type'] : 'referrals'; $filters = report_filters($_GET);
$sort = (string) ($_GET['sort'] ?? 'submitted_at'); $direction = strtolower((string) ($_GET['dir'] ?? 'desc')) === 'asc' ? 'asc' : 'desc'; $page = max(1, (int) ($_GET['page'] ?? 1)); $perPage = 20;
try {
    $options = report_options($businessId); $summary = report_earnings_summary($businessId, $filters); $charts = report_chart_data($businessId, $filters);
    $total = $type === 'referrals' ? report_referral_count($businessId, $filters) : 0;
    $rows = match ($type) { 'commissions' => report_commissions($businessId, $filters), 'campaigns' => report_campaign_performance($businessId, $filters), 'earnings' => [], default => report_referrals($businessId, $filters, $sort, $direction, $perPage, ($page - 1) * $perPage) };
} catch (Throwable $exception) { app_log('Business reports failed: ' . $exception->getMessage()); $options = ['campaigns' => [], 'products' => [], 'referrers' => []]; $summary = []; $charts = ['monthly_referrals'=>[], 'monthly_commission'=>[], 'campaign_performance'=>[], 'status_distribution'=>[]]; $rows = []; $total = 0; set_flash('danger', 'Report data could not be loaded. Please try again.'); }
$query = static function (array $changes = []) use ($type, $filters, $sort, $direction): string { return http_build_query(array_filter(array_merge(['type'=>$type, 'sort'=>$sort, 'dir'=>$direction], $filters, $changes), static fn($value) => $value !== '' && $value !== null && $value !== false)); };
$sortUrl = static function (string $column) use ($query, $sort, $direction): string { return url('business/reports.php?' . $query(['sort'=>$column, 'dir'=> $sort === $column && $direction === 'asc' ? 'desc' : 'asc', 'page'=>1])); };
$pageTitle = 'Business Reports | ' . APP_NAME; require_once __DIR__ . '/../includes/header.php';
?>
