<section class="dashboard-welcome business-welcome"><div><span class="eyebrow"><i class="bi bi-clipboard-data"></i> Module 8</span><h1>Reports &amp; Exports</h1><p>Track referral outcomes, commissions, campaign performance, and earnings in one place.</p></div><a class="btn btn-light border" href="<?= e(url('business/dashboard.php')) ?>">Back to dashboard</a></section>
<div class="report-tabs mt-4"><?php foreach (['referrals'=>['Referral Report','bi-person-lines-fill'], 'commissions'=>['Commission Report','bi-cash-coin'], 'campaigns'=>['Campaign Performance','bi-graph-up-arrow'], 'earnings'=>['Earnings Summary','bi-wallet2']] as $key => [$label,$icon]): ?><a class="<?= $type === $key ? 'active' : '' ?>" href="<?= e(url('business/reports.php?' . $query(['type'=>$key, 'page'=>1]))) ?>"><i class="bi <?= e($icon) ?>"></i><?= e($label) ?></a><?php endforeach; ?></div>
